Como corrigir:
1. Corrija as palavras-chave e tipos:
Em vez de:
Struct morada{
 string rua;
 long codigoPostal;
 string localidade;
};
Use:
struct Morada {
 string rua;
 string codigoPostal;
 string localidade;
};
2. Corrija a estrutura Pessoa:
struct Pessoa {
 int id;
 string nome;
 string dataNascimento;
 Morada morada;
};
3. Implemente a função inserirPessoa corretamente:
Pessoa inserirPessoa() {
 Pessoa p;
 // Pedir e ler todos os dados do utilizador
 return p;
}
4. Implemente a função main conforme o exemplo fornecido:
int main() {
 int n;
 cout > n;
 Pessoa* pessoas = new Pessoa[n];
 for (int i = 0; i < n; i++) {
 pessoas[i] = inserirPessoa();
 }
 cout << "Número total de pessoas registadas: " << n << endl;
 delete[] pessoas;
 return 0;
}

