Como corrigir:
Exemplo de código incorreto:
void inserirNodo(nodo*& raiz, int valor) { ... }
if (valor > raiz->dados) { inserirNodo(raiz->esq, valor); }
else { inserirNodo(raiz->dir, valor); }

Código corrigido:
nodo* inserirNodo(nodo* raiz, int valor) {
 if (raiz == NULL) {
 nodo* novo = new nodo;
 novo->dados = valor;
 novo->esq = NULL;
 novo->dir = NULL;
 return novo;
 }
 if (valor dados)
 raiz->esq = inserirNodo(raiz->esq, valor);
 else
 raiz->dir = inserirNodo(raiz->dir, valor);
 return raiz;
}

Na main, deve-se fazer:
raiz = inserirNodo(raiz, valores[i]);

