Como corrigir:
1. Definir a estrutura nodo corretamente:
struct nodo {
 int dados;
 nodo* esq;
 nodo* dir;
};
2. Implementar a função inserirNodo com a assinatura correta e lógica de inserção:
nodo* inserirNodo(nodo* raiz, int num) {
 if (raiz == NULL) {
 nodo* novo = new nodo;
 novo->dados = num;
 novo->esq = NULL;
 novo->dir = NULL;
 return novo;
 }
 if (num dados)
 raiz->esq = inserirNodo(raiz->esq, num);
 else
 raiz->dir = inserirNodo(raiz->dir, num);
 return raiz;
}
3. Criar a função main, declarar a raiz como nodo* root = NULL; e inserir todos os valores pedidos usando inserirNodo.
4. Implementar as funções existe, imprimirFolhas e somaValores conforme os exemplos fornecidos.

